entries.command:
cd . && grep -rn "outputs\b\|\.outputs\|ended" src --include=*.ts | grep -v test | grep -v "^src/core/rollout.ts" | head; python3 - <<'EOF'
p='src/core/rollout.ts'; s=open(p).read()
pairs=[('''  lastLine: number;
  /** Its turn completed or aborted: no output by then means it never finished. */
  ended: boolean;
};''','''  lastLine: number;
  /** Got a final result. Output that names a session or cell still running does not count. */
  finished: boolean;
  /** Its turn completed or aborted: not finished by then means it was cut off. */
  ended: boolean;
};'''),
('''      const session = /^Process running with session ID (\\S+)/m.exec(text)?.[1];
      const cell = /^Script running with cell ID (\\S+)/m.exec(text)?.[1];
      if (session) scan.running.set(`session:${session}`, call);
      else if (cell) scan.running.set(`cell:${cell}`, call);
      return;''','''      const session = /^Process running with session ID (\\S+)/m.exec(text)?.[1];
      const cell = /^Script running with cell ID (\\S+)/m.exec(text)?.[1];
      if (session) scan.running.set(`session:${session}`, call);
      else if (cell) scan.running.set(`cell:${cell}`, call);
      call.finished = !session && !cell;
      return;'''),
('''    lastLine: index,
    ended: false,
  };''','''    lastLine: index,
    finished: p.type === "web_search_call",
    ended: false,
  };'''),
('''  const done = c.outputs.length > 0;
  const status = (failed: boolean) =>
    failed || (!done && ended) ? "failed" : done ? "completed" : "inProgress";''','''  const status = (failed: boolean) =>
    failed || (!c.finished && ended) ? "failed" : c.finished ? "completed" : "inProgress";''')]
for a,b in pairs:
    assert s.count(a)==1, a[:70]; s=s.replace(a,b)
open(p,'w').write(s)
EOF
export PATH=$PWD/node_modules/.bin:$PATH && vp test run src/core 2>&1 | grep -E "×|Tests"
